'use strict';
let shopState={items:{},free:[],mode:'kits'},shopFilter='all',catalogRows=[];
async function loadCatalog(){catalogRows=await C.catalog();for(const row of catalogRows){const list=D.catalog[row.category],i=list.findIndex(x=>x.name===row.name),item={...row.data,name:row.name};if(i>=0)list[i]={...list[i],...item};else list.push(item);}}
function kitSelected(k){const entries=Object.entries(shopState.items).filter(([id])=>!shopState.free.includes(id));return k.ready&&entries.length===k.rows.length&&k.rows.every(x=>shopState.items[x.key]===1);}
function shopQuote(){return ND_SHOP.quote(shopState,D);}
function shopChange(fn){const old=E.clone(shopState);try{fn();shopQuote();rememberWizard();showEquipment();}catch(e){shopState=old;showEquipment();portalError(e);}}
function shopDetail(x){modal(x.displayName||x.name,`<p>${esc(x.description)}</p><p>${esc(shopParams(x))}</p><button id="shop-detail-close">Закрыть</button>`);$('#shop-detail-close').onclick=closeModal;}
function shopParams(x){return [x.damage!==undefined?'Урон '+x.damage:'',x.range?'Дальность '+x.range:'',x.slot||'',x.armor!==undefined?'Броня '+x.armor:'',x.slots?'Хром '+x.slots:'',x.type||''].filter(Boolean).join(' · ');}
function showEquipment(){portalView='wizard';let q;try{q=shopQuote();}catch(e){portalShell('Проверь оснащение','Каталог изменился.',`<p>${esc(e.message)}</p><button id="reset-shop">Очистить предварительное оснащение</button>`);$('#reset-shop').onclick=()=>{shopState={items:{},free:[],mode:'kits'};rememberWizard();showEquipment();};return;}const all=ND_SHOP.all(D),kits=ND_SHOP.kits(D);portalShell('С чем ты войдёшь в город?','04 / Оснащение · готовый комплект или собственная сборка. Выбор не задаёт класс персонажа.',`<div class="shop-budget" role="status">Бюджет: <b>2 000</b> <span>Потрачено: <b>${q.total}</b></span><span>Осталось: <b>${q.left}</b></span></div><div class="library-toolbar"><button id="shop-kits" ${shopState.mode==='kits'?'class="yellow"':''}>Готовый комплект</button><button id="shop-custom" ${shopState.mode==='custom'?'class="yellow"':''}>Собрать самостоятельно</button></div>${shopState.mode==='kits'?`<div class="kit-grid">${kits.map(k=>`<article class="panel kit-card ${kitSelected(k)?'is-selected':''}"><div class="kit-portrait"><img src="assets/${k.id}.jpg" alt="${esc(k.name)}" loading="lazy"></div><button type="button" class="kit-select" data-kit="${k.id}" aria-pressed="${kitSelected(k)}" ${!k.ready||k.price>2000?'disabled':''}><span>${kitSelected(k)?'✓ Комплект выбран':'Выбрать комплект'}</span><span aria-hidden="true">${kitSelected(k)?'●':'↗'}</span></button><div class="kit-body"><h2>${esc(k.name)}</h2><p>${esc(k.description)}</p><ul>${k.rows.map(x=>`<li>${esc(x.displayName||x.name)} — ${x.price}</li>`).join('')}</ul>${k.id==='netrunner'?'<p>Два различных базовых Червя — бесплатно</p>':''}<p>${k.ready?`Стоимость: <b>${k.price}</b> · Остаток: <b>${2000-k.price}</b>`:'Ожидает параметров недостающего оружия в справочнике'}</p></div></article>`).join('')}</div>`:`<div class="shop-filters"><button data-shop-filter="all" ${shopFilter==='all'?'class="yellow"':''}>Все</button>${Object.entries(ND_SHOP.groups).map(([id,name])=>`<button data-shop-filter="${id}" ${shopFilter===id?'class="yellow"':''}>${name}</button>`).join('')}</div><div class="shop-items">${all.filter(x=>ND_SHOP.allowed(x)&&(shopFilter==='all'||(x.shopCategory||x.cat)===shopFilter)).map(x=>`<article class="panel shop-product ${shopState.items[x.key]?'is-selected':''}"><div class="product-top"><span class="eyebrow">${esc(ND_SHOP.groups[x.shopCategory||x.cat]||labels[x.cat])}</span><span class="product-price">${x.price} <small>эдди</small></span></div><h3>${esc(x.displayName||x.name)}</h3><p class="product-params">${esc(shopParams(x))}</p><p class="product-description">${esc(x.description)}</p><div class="product-status">${shopState.items[x.key]?`✓ В оснащении: ${shopState.items[x.key]} шт.`:'Доступно на старте'}</div><div class="product-actions"><button class="product-add" data-shop-add="${esc(x.key)}" ${q.left<x.price||x.cat!=='consumables'&&shopState.items[x.key]?'disabled':''}>${shopState.items[x.key]?(x.cat==='consumables'?'+ Добавить ещё':'✓ Добавлено'):'+ Добавить'}</button><button data-shop-detail="${esc(x.key)}">Подробнее</button></div></article>`).join('')}</div>`}<section class="panel shop-cart"><header class="equipment-heading"><div><span class="eyebrow">ТВОЙ АРСЕНАЛ</span><h2>Предварительное оснащение</h2></div><span class="equipment-total">${q.rows.reduce((n,x)=>n+x.quantity,0)} шт. <b>${q.total} эдди</b></span></header>${q.rows.length?`<div class="cart-list">${q.rows.map(x=>`<div class="cart-row"><div class="cart-item"><span class="eyebrow">${esc(ND_SHOP.groups[x.shopCategory||x.cat]||labels[x.cat])}</span><strong>${esc(x.displayName||x.name)}</strong>${shopState.free.includes(x.key)?'<span class="cart-bonus">В комплекте с декой</span>':''}</div><div class="cart-quantity">${x.cat==='consumables'?`<label><span>Количество</span><input aria-label="Количество: ${esc(x.displayName||x.name)}" type="number" min="1" max="999" value="${x.quantity}" data-shop-qty="${esc(x.key)}"></label>`:'<span class="micro">1 шт.</span>'}</div><div class="cart-price">${shopState.free.includes(x.key)?'Бесплатно':`${x.price*x.quantity} <small>эдди</small>`}</div><button class="cart-remove" aria-label="Убрать: ${esc(x.displayName||x.name)}" data-shop-remove="${esc(x.key)}">Убрать</button></div>`).join('')}</div>`:'<p class="cart-empty">Пока пусто. Выбери комплект или добавь предметы из каталога — весь неиспользованный бюджет останется у персонажа.</p>'}</section>${q.deck?`<section class="panel worm-panel"><header class="equipment-heading"><div><span class="eyebrow">СТАРТОВЫЙ СОФТ / НЕЙРО-ДЕКА</span><h2>Два Червя на выбор</h2></div><span class="worm-counter ${shopState.free.length===2?'complete':''}" role="status">Выбрано <b>${shopState.free.length} из 2</b></span></header><p class="worm-intro">Выбери две разные программы бесплатно. Описания и параметры — из общего справочника.</p><div class="worm-grid">${all.filter(x=>x.cat==='programs'&&ND_SHOP.allowed(x)).map(x=>`<label class="worm-choice ${shopState.free.includes(x.key)?'is-selected':''}"><input type="checkbox" data-free-worm="${esc(x.key)}" ${shopState.free.includes(x.key)?'checked':''} ${shopState.free.length===2&&!shopState.free.includes(x.key)?'disabled':''}><span class="worm-content"><span class="worm-title">${esc(x.displayName||x.name)}</span><span class="worm-description">${esc(x.description)}</span><span class="worm-parameters">${x.target?`<span><b>Цель</b>${esc(x.target)}</span>`:''}${x.difficulty?`<span><b>Сложность</b>${esc(x.difficulty)}</span>`:''}</span><span class="worm-status">${shopState.free.includes(x.key)?'✓ Программа выбрана':'Включить в комплект'}</span></span></label>`).join('')}</div><p class="hint worm-footnote">Бонус доступен только при создании. Чтобы заменить программу, сначала сними выбор с одной из двух.</p></section>`:''}<div class="wizard-actions"><button id="equipment-back">← Назад</button><button id="equipment-next" class="yellow">Создать персонажа</button></div>`);
$('#shop-kits').onclick=()=>{shopState.mode='kits';rememberWizard();showEquipment();};$('#shop-custom').onclick=()=>{shopState.mode='custom';rememberWizard();showEquipment();};$('#equipment-back').onclick=goBack;$('#equipment-next').onclick=finishCharacter;
document.querySelectorAll('[data-kit]').forEach(b=>b.onclick=()=>shopChange(()=>{const k=kits.find(x=>x.id===b.dataset.kit);if(kitSelected(k))return;shopState.items=Object.fromEntries(k.rows.map(x=>[x.key,1]));shopState.free=[];}));document.querySelectorAll('[data-shop-filter]').forEach(b=>b.onclick=()=>{shopFilter=b.dataset.shopFilter;showEquipment();});document.querySelectorAll('[data-shop-add]').forEach(b=>b.onclick=()=>shopChange(()=>{const k=b.dataset.shopAdd;shopState.items[k]=(shopState.items[k]||0)+1;}));document.querySelectorAll('[data-shop-detail]').forEach(b=>b.onclick=()=>shopDetail(all.find(x=>x.key===b.dataset.shopDetail)));document.querySelectorAll('[data-shop-qty]').forEach(b=>b.onchange=()=>shopChange(()=>{shopState.items[b.dataset.shopQty]=+b.value;}));document.querySelectorAll('[data-shop-remove]').forEach(b=>b.onclick=()=>shopChange(()=>{const k=b.dataset.shopRemove;delete shopState.items[k];shopState.free=shopState.free.filter(id=>id!==k);if(all.find(x=>x.key===k).name.includes('Third-Eye')){for(const id of shopState.free)delete shopState.items[id];shopState.free=[];}}));document.querySelectorAll('[data-free-worm]').forEach(b=>b.onchange=()=>shopChange(()=>{const id=b.dataset.freeWorm;if(b.checked){shopState.free.push(id);shopState.items[id]=1;}else{shopState.free=shopState.free.filter(x=>x!==id);delete shopState.items[id];}}));}
function showCatalogAdmin(){portalView='catalog';portalShell('Справочник мастера.','Изменения доступны всем игрокам после входа или обновления. Удалённые позиции сохраняются в старых карточках.',`<button id="catalog-new" class="yellow">+ Добавить предмет или перк</button><div class="shop-items">${ND_SHOP.all(D).filter(x=>!x.archived).map(x=>`<article class="panel"><h3>${esc(x.displayName||x.name)}</h3><p>${esc(labels[x.cat])} · ${x.price??'Цена не задана'}</p><button data-catalog-edit="${esc(x.key)}">Изменить</button><button data-catalog-delete="${esc(x.key)}">Удалить</button></article>`).join('')}</div>`);$('#catalog-new').onclick=()=>catalogEdit();document.querySelectorAll('[data-catalog-edit]').forEach(b=>b.onclick=()=>catalogEdit(ND_SHOP.all(D).find(x=>x.key===b.dataset.catalogEdit)));document.querySelectorAll('[data-catalog-delete]').forEach(b=>b.onclick=()=>{const x=ND_SHOP.all(D).find(x=>x.key===b.dataset.catalogDelete);modal('Удалить из справочника?',`<p>${esc(x.displayName||x.name)}</p><p>Новые покупки будут закрыты. Записи в существующих карточках сохранятся.</p><button id="archive-item">Да, удалить</button>`);$('#archive-item').onclick=async()=>{try{await persistCatalog(x.cat,x.name,{...x,archived:true});closeModal();showCatalogAdmin();}catch(e){error(e);}};});}
async function persistCatalog(cat,name,data){const row=catalogRows.find(x=>x.category===cat&&x.name===name);const r=await C.saveCatalog(cat,name,data,row?.revision);if(!r?.length)throw Error('Справочник изменён в другом окне. Обнови страницу.');await loadCatalog();}
function catalogEdit(item){modal(item?'Изменить запись':'Новая запись',`<form id="catalog-form"><label class="field">Категория<select name="cat" ${item?'disabled':''}>${Object.entries(labels).map(([id,label])=>`<option value="${id}" ${item?.cat===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Название<input name="name" required maxlength="200" value="${esc(item?.displayName||item?.name||'')}"></label><label class="field">Описание<textarea name="description" required>${esc(item?.description||'')}</textarea></label><div class="two-cols">${['price','damage','range','slot','armor','slots','type','placement','cost','target','difficulty'].map(k=>`<label class="field">${esc({price:'Цена, эдди',damage:'Базовый урон',range:'Дальность',slot:'Руки',armor:'Ячейки брони',slots:'Слоты Хрома',type:'Тип',placement:'Размещение',cost:'Стоимость перка, ОО',target:'Цель',difficulty:'Сложность'}[k])}<input name="${k}" value="${esc(item?.[k]??'')}"></label>`).join('')}</div><label class="field">Категория магазина<select name="shopCategory">${Object.entries(ND_SHOP.groups).map(([id,name])=>`<option value="${id}" ${item?.shopCategory===id?'selected':''}>${name}</option>`).join('')}</select></label><label><input name="startAllowed" type="checkbox" ${item?.startAllowed?'checked':''}> Явно разрешить для старта 2 000</label><p class="hint">Оружие: урон 0–2; броня: 0–1; имплант: ровно 1 слот; программы: тип «Базовый червь». Для неизвестных цен разрешение не действует.</p><button type="submit" class="yellow">Сохранить</button></form>`);$('#catalog-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const x={...(item||{}),name:item?.name||f.elements.name.value.trim(),displayName:f.elements.name.value.trim(),description:f.description.value,shopCategory:f.shopCategory.value,startAllowed:f.startAllowed.checked,archived:false};for(const k of ['price','damage','range','slot','armor','slots','type','placement','cost','target','difficulty']){const v=f.elements[k].value.trim();if(v===''){delete x[k];continue;}x[k]=['price','damage','armor','slots','cost'].includes(k)?Number(v):v;if(typeof x[k]==='number'&&(!Number.isSafeInteger(x[k])||x[k]<0))throw Error('Числовые параметры должны быть целыми и неотрицательными');}const cat=item?.cat||f.cat.value;if(!x.displayName)throw Error('Укажи название');if(!item&&D.catalog[cat].some(i=>i.name===x.name))throw Error('Такое название уже существует');if(x.startAllowed&&!ND_SHOP.allowed({...x,cat}))throw Error('Параметры не соответствуют стартовым ограничениям');await persistCatalog(cat,x.name,x);closeModal();showCatalogAdmin();}catch(e){error(e);}};}
